// ---- Update log: each player sees the updates they missed since their last login ----
const UPDATES = [
  { id: 20, title: 'Laser swords and shields', items: ['Laser swords with custom colors and hilts, previewed in the shop', 'Melee only fires with a melee weapon equipped; the offhand blue shield blocks', 'Saber mod station on your ship'] },
  { id: 21, title: 'Sound, music and B.U.R.P.', items: ['Calm beep-boop music (Menu → Settings to switch it off)', 'B.U.R.P. has a robot voice now', 'Softer footsteps and sound effects on nearly everything'] },
  { id: 22, title: 'Space police bounties', items: ['Marshal Rook posts random bounties across the galaxy', 'Rank up your bounty-hunter skill for gear and big payouts paid into your bank', 'No more raiders jumping you in space unless you shoot first'] },
  { id: 23, title: 'Safer and fairer', items: ['Safe fishing spots', 'Mezar spawns you inside the walls', 'Bank part of your credits', 'No more shooting (or getting shot) through walls', 'Betting has its own pit with a clear scoreboard'] },
  { id: 24, title: 'The Moon and notebook weapons', items: ['Earth\'s Moon is open: low gravity, craters and a dome city', 'Sword-gun, nunchucks, claws, scythe, driller, twin master swords, crossbow and more', 'New pets and helmets'] },
  { id: 25, title: 'Gun mods and ordnance', items: ['Paint your guns and swap rounds (laser to void)', 'Unlock grenades: press Z to throw', 'Gun bench on your ship · L launches your ship'] },
  { id: 26, title: 'Ocean World and prettier space', items: ['Swim underwater and walk into the domes', 'Landing on planets no longer locks you in', 'Nebula, glowing atmospheres and dust streaks in space'] },
  { id: 27, title: 'Velocity, the racing planet', items: ['Every car looks different now', 'Free drive through the canyons and badlands (X, or Garage Gus)', 'Big airtime pays credits'] },
  { id: 28, title: 'Canyon sprints', items: ['Races are point-to-point sprints from the pits across the planet (770–910 m)', 'Canyon walls line every course, with gates every 80 m and six jumps', 'The Velocity map is much bigger', 'Space: smaller, dimmer stars and planets spread further apart', 'This update log, so you never miss anything'] },
  { id: 29, title: 'New armor styles', items: ['9 new armor sets, each with its own silhouette: Gladiator Kit, Deep Diver Suit, Lunar EVA, Shadow Wraps, Robo Chassis, Seer Robes, Tank Suit, Mech Frame and Drome Warplate', 'The old sets got real makeovers too (Recon ghillie, Heavy Plate pauldrons, Hive carapace, Frost fur coat and more)', 'Buy new sets in the Wardrobe once you reach their level; tap any set to try it on first', 'Phone flight controls: just the stick, FIRE and a new BOOST button (the on-foot buttons hide while flying)'] },
  { id: 30, title: 'Fort Ironrock and war vehicles', items: ['New world: Fort Ironrock, the asteroid army base (between Earth and Mezar)', 'Drive a Battle Car (ram spikes + twin MGs), a Battle Tank (cannon) or a Battle Mech (missile salvos + jump jets): press V or Menu → Vehicle on any open planet', 'Quartermaster Brix sells vehicles; Dr. Volta researches armor, weapons and engines', '4 new quests ending with Warlord Krag; finish the first one for a free Battle Car', 'The arena betting scoreboard no longer follows you off the arena planet']},
  { id: 31, title: 'Chapter 6: Earth Sky', items: ['New world above Earth: floating islands joined by sky bridges', 'The Sky Air Base, the Floating City (droids), the Deep Sky Forest, a rebel camp and Drome\'s Sky Fortress', 'Fight Drome, Lord of the Setting Sun, for the Sunslayer Cape', 'Fall off an island and the Air Base fishes you out (it stings)']},
  { id: 32, title: 'Zarlich and Vector are open', items: ['Chapter 7, Zarlich: violet storm world with Flaglem-ti, wild Noptiles, T-rexes, Gosa-lem, Devil Light Rays and flying Tube Sharks; boss: the Storm Mother', 'Chapter 8, Vector: the dark world with shades, the Field of Eyes and the true final boss, the Watcher in the Maw (Cape of the Rising Sun)', 'New pets: Tube Shark and Flaglem-ti (Zix on Zarlich)']},
  { id: 33, title: "Earth: Forest of Life and the Super Swift Arena", items: ['Two new signposts in Earth town lead to them', 'Forest of Life (Lv 8–14): the Tree of Life heals you; Snapvines, Spriggans, Glowmoths and the Rot King; reward: the Thornblade', 'Super Swift Arena: an 11-boss rush, every boss scaled to your level; clear them all for the Swift Champion Cape']},
  { id: 34, title: 'All 20 floors of the Zeltac Ship', items: ['Take the elevator in the plaza (back right corner)', 'Market decks (shops, an arms dealer), Residential rings, Hydroponics bays (fish buyer), Neon Arcades (slot machines)', 'Hostile Engine decks and Alien Quarters get harder the higher you go', "Floor 20 is the Captain's Bridge"]},
  { id: 35, title: 'Character creator', items: ['New Face tab in the Wardrobe: skin (including alien colors), eyes, mouth, hair and hair color', '19,200 possible faces, inspired by the head-design sheet; hit Random for a surprise', 'Choose "No helmet" to show your face; other players see it too']},
  { id: 36, title: 'Welcome to New Jamestown', items: ["Earth's safe zone is now New Jamestown, a walled capital city twice the size", 'Main Street, a fountain plaza, Town Hall, bank, clinic, gun shop, store, pet shop, fish market, diner, hotel and tailor', 'New citizens: Mayor Holloway (town news), Ada the Tailor (wardrobe), Cookie, Auntie Paws, Gil, Scoop the newsie, Banjo Bob, Officer Dent, Hotel Hank, plus a crowd on the streets', 'Signposts to the Forest of Life and Super Swift Arena are by the city gate; the dropship pad is in the north-east']},
  { id: 37, title: 'World raids and Commander mode', items: ["Every 15 minutes Drome's remnants raid a different planet for 5 minutes; a bar at the bottom of the screen shows where (tap it to fly there)", 'Raiders come in waves at the edge of town, scaled to your level, with a raid boss at wave 6; every raider drops Raid Tokens', 'Spend tokens with the Mayor or at Fort Ironrock (Raid Cape, Commander Banner, materials, credits)', 'Commander mode is back as the War Table: an overhead view where you spend command points to drop squads and bosses on the troopers playing that planet']},
  { id: 38, title: 'The Starlight Lounge, 9 unique floors and a world detail pass', items: ['The Zeltac Ship now has 9 floors that each look different (it was 20 with repeats)', 'Floor 5: the Starlight Lounge, a bar with a stage, booths and a disco ball', 'Six regulars to romance: Nyra Voss (ace pilot), Grix (rock poet), Juno Sparks (mechanic), Rhett Calloway (smuggler), Vesper (from Vector) and PIP-9 (a robot studying love). Chat, flirt, give gifts, go on dates', 'Go from Stranger to Partner: partners give a perk, visit your ship and send you messages', 'Every outdoor world got ground detail (flowers, mushrooms, cacti, scrap, crystals, spikes and more), floating particles in the air and birds on green worlds', 'Fishing docks can be stood on; enemies no longer push you out of safe rings']},
  { id: 39, title: 'Ship customizer and scavenging', items: ['Mod your ship: 10 paints, 7 accent colors, plus wings, engines, noses, fins and extras (missile pods, armor plating, trophy spikes and more)', 'Parts change your speed, hull and laser damage; other players see your ship', 'Some parts start unlocked; the rest are scavenged from glowing salvage drifting in space (fly through it) or salvage crates hidden on planets (walk over them)', 'Use the Ship customizer on your bridge or ask Brakka on the Zeltac Ship', 'The "Leave the helm" / "Land" prompt no longer covers your ship']},
  { id: 40, title: 'New galaxy map', items: ['The galaxy map is now a top-down chart of every world, the asteroid belt and the sun', 'Tap a world to see its level range, then autopilot there or fly there yourself', 'Shows where you are, which worlds are locked and where a raid is happening']},
  { id: 41, title: 'Cities come alive', items: ['Every hub got a life pass: market stalls, carts, crates, lamps, benches, signs, string lights and themed props (honey pots in Bug City, holo-ads and vending machines in Robot City, boats and nets in Port Kelp, rovers on the Moon, tents and jeeps at Fort Ironrock, and more)', 'Crowds of locals now wander between spots in every city and stop to hang out', 'Towns glow at night with a warm city light']},
  { id: 42, title: 'Ship decorating (building retired)', items: ['Base building on planets is gone; instead, decorate your ship\'s rooms (Menu → Decorate, or G)', '50 pieces of furniture across Living, Bedroom, Kitchen, Fun, Decor, Tech and Build: sofas, beds, aquariums, arcade cabinets, pool table, jukebox, fireplace, trooper statue, weapon rack, saber display, holo-map table and more', 'Lots are free; the rest you buy once with credits and place as many as you like', 'Some furniture does things: nap in a bed, watch the news on the holo-TV, change music on the jukebox, open the galaxy map on the holo-table, grab a coffee']},
  { id: 43, title: 'The War Table has a purpose', items: ['Support mode: call in airstrikes, sentry turrets, supply drops, allied trooper squads and an orbital lance on any open planet', 'Great during raids: points recharge faster, and your support kills earn Raid Tokens', 'Invade mode is still there for dropping enemy squads on other players']},
  { id: 44, title: 'The Residential Ring', items: ['Zeltac floor 3 is now a real neighborhood: 12 apartments around a park with a fountain, playground, community garden, mailbox and kids running around', 'The six Starlight Lounge regulars live here; once you are friends, knock and visit their themed apartment (Nyra has ship models, Grix a rock garden, Juno a workshop, and so on)', '"Spend the evening" at their place to grow closer', 'Dating someone? Invite them to live on your ship: they move into your quarters and leave you gifts']},
  { id: 45, title: 'Graphics styles', items: ['Menu → Settings → Graphics: Classic PS1, PS1 Glow (new default), Crisp Toon, Neon Night or Golden Hour', 'Adds glow on lights and neon, richer color and optional scanlines']},
  { id: 46, title: 'New Jamestown, twice as big', items: ['The capital is now a 90-meter walled city with wide boulevards, sidewalks, a big fountain plaza, a columned Town Hall, 21 buildings (arcade, cinema, garage, apartments) and a park with a pond and gazebo', 'Earth\'s wilds were pushed outward to make room, so the whole planet is bigger too', 'More citizens, more street life, parked hover cars']},
  { id: 47, title: 'Fixes: racing, bank, clutter', items: ['Racing works now: talking to Race Marshal Vroom always gets you to the Race menu (accepting his quest used to just close the conversation)', 'Races are simpler time trials: no walls, no AI traffic, big gates, a light beam over the next gate, and gold/silver/bronze times', 'The bank has a clean Deposit / Withdraw layout', 'Ground clutter and city props no longer spawn inside buildings and structures', 'Quest-giving shopkeepers reopen their shop menu after you accept or decline']},
  { id: 48, title: 'Render styles', items: ['Menu → Settings → Render style: Retro PS1, HD Stylized or Semi-Realistic (the game reloads to switch)', 'HD styles render at full resolution with smooth textures, real-time sun shadows, bloom on lights and film-style color', 'Semi-Realistic uses physically based materials with surface relief; HD Stylized uses cel-shaded toon lighting']},
  { id: 49, title: 'Combat feel, Codex and New Game+', items: ['Hits now show damage numbers (orange for big hits), guns have muzzle flashes, kills flash, bosses go down in a pillar of light, and explosions shake the screen', 'Level-ups fire a golden beam', 'Menu → Codex: 36 achievements with credit rewards, 3 daily challenges (the same for everyone each day), a Bestiary of every creature you have beaten, and your lifetime stats', 'Finish the Zeltac storyline to roll the ending credits and unlock Ascension (New Game+): tougher enemies, more XP and an Ascendant cape', 'New settings: look speed, invert look, field of view, screen shake and damage numbers']},
  { id: 50, title: 'Lore, controls and photo mode', items: ['Codex → Lore: an entry for all 17 worlds plus the factions and figures behind the war, unlocked as you explore', 'The first time you land on a new world you get a big title card', 'Press F1 (or Menu → Controls) for the full controls list; the title screen key list is up to date too', 'Photo mode: press P (or Menu → Photo mode) to hide the HUD and gun; K saves a picture', 'New hotkeys: C opens the Codex, M opens the galaxy map on your ship', 'One-time tips help new troopers find medkits, the ship, vehicles, decorating and raids', 'Codex → Leaderboards: see how you rank against every trooper for level, kills, bosses, Super Swift rounds, raids, achievements, fish and each race track', 'Fixed long lists in menus squashing their rows together']},
  { id: 51, title: 'Boarding, drones, Chapter 5 and a new HUD', items: ['Brand-new HUD: glass panels, a compass tape with your objective marker, a round radar, segmented health, and a menu that opens as a grid of tiles', 'Phones: tidy right-hand column for Reload, Swap, Grenade and a new HEAL button (shows your medkit count). Tap your ammo to reload. Desktop: click the medkit chip or press H', 'Board ships in space! Freighters, raider corsairs, Drome cutters and hive ships drift between worlds. Fly close, dock, clear the crew and loot the hold for credits, ship parts and drone parts', 'Combat drone: buy one at the drone bay on your ship (or Fort Ironrock / Brakka). Upgrade its twin blasters, micro-missiles and repair beam, and pick a paint', 'Chapter 5 · The Dark Fleet: chase Drome\'s fleet from Robot City, board the flagship Eclipse, face Admiral Sable, then retake Fort Ironrock. The whole story now runs in order, Chapter 1 to 8', 'Epilogue: after the Watcher falls, Captain Vega has one last thing for you', 'Codex → Ending replays the ending, now a real cutscene with fast-forward and skip', 'Players online: see who is on which world and Join them (Menu → Players, or from the Leaderboards)', 'Change your callsign any time in Settings', 'Fixes: the leaderboard picker no longer shows up in other menus, race gates now face the road, Ada the Tailor no longer hands out Robot City quests on Earth, and the two Fenns stopped sharing quests']},
  { id: 52, title: 'HUD fixes', items: ['The new HUD now looks right on every phone: the old blue panels and button positions were showing through on some devices', 'The Grenade button is called Ordnance again', 'Landscape on phones: the quick-action column no longer covers the radar, and the joystick no longer sits on your health panel']},
  { id: 53, title: 'Towns, pads and the armory', items: ['Townsfolk no longer spawn stacked on top of each other and standing still (Moon, Mezar, Capitone, Robot City and Earth Sky were worst). They now spread out and walk around', 'Landing pads that were clipped into buildings or blocking doorways now move to the nearest open ground (the Moon pad is outside the dome now)', 'The armory gun rack is mounted flat against the wall, with six different guns on pegs', 'The weapon panel no longer shows the gun name, just your ordnance charges', 'The Reload button hides when your gun has unlimited ammo']},
  { id: 54, title: 'Wizardry', items: ['The full staff line from the notebooks, Lvl 1 to Lvl 100: Apprentice, Ember, Lightning, Glacier, Plague, Blast, Archmage, Stormcaller, Inferno, Void, and the Staff of the Setting Sun', 'New spell effects: arcane sparks that jump to nearby foes, frost that slows and can freeze enemies solid, and Blast Staff explosions', 'Staffs never need ammo: they recharge their mana between bursts', 'Merla the Wizard has opened a staff shop in New Jamestown (by the fountain). Maxurge on Capitone and Seer Ixa on the Zeltac Ship sell the stronger staffs', "The Wizard's Path: three quests from Merla that end with the Staff of the Setting Sun", 'Wardrobe: Wizard Robes and a Wizard Hat']},
  { id: 55, title: 'ART OF WAR: SETTING SUN 1.0', items: ['Version 1.0 is here. Thank you for flying the Setting Sun!', 'The full story, Chapters 1 to 8 plus the epilogue; 17 worlds; boarding, racing, raids, fishing, pets, drones, romance, staffs and New Game+', 'Final bug sweep: every world, deck, menu and quest checked; townsfolk walk more smoothly and use less of your phone']},
  { id: 56, title: '1.0.1', items: ['Fixed the flickering streets in New Jamestown: the roads, sidewalks, plaza and crosswalks were drawn at the same height and fought each other. Each layer now sits cleanly on top of the last']},
  { id: 57, title: '1.1: A proper ship, and real spells', items: ['Your ship has been refitted: plated deck floors, ribbed hull walls and paneled ceilings, all at the right scale, with a guide stripe down the corridor and framed doorways', 'Every room has its own look and lighting: carpeted wood-paneled quarters, a steel armory, a grated cargo bay, a white-tiled med bay, a marble-and-red trophy hall, a greenhouse garden and a hazard-striped hangar', 'Every room has a job. Quarters: sleep for full health and Well Rested (+15% XP for 15 min), wardrobe, personal log. Armory: gun rack, workbench, ordnance rack that refills your charges. Cargo bay: sell loot from the ship. Med bay: healing pod and an armor stim (take 25% less damage for 10 min). Trophy hall: trophies and the Hall of Records leaderboards. Garden: grows medkits, plus a fish tank. Hangar: vehicle bay, your bike, and a launch pad', 'The bridge has a console row and a proper captain\'s chair', 'Staffs and wands now cast named spells (Fireball, Chain Lightning, Ice Shard, Plague Cloud, Blast Wave, Void Rift, Sunburst and more) from a mana bar that refills on its own. No rounds and no reloading', 'Active buffs (Well Rested, Armor Stim) show on the HUD']},
  { id: 58, title: '1.2: The soundtrack', items: ['Real music! New Jamestown has its own theme, Velocity races to an overture, Fort Ironrock rides a tidal wave, and the rest of the galaxy has its own groove', 'Fights switch to battle music, and bosses get their own apocalyptic theme. Music crossfades cleanly between places and moments', 'Your ship alternates between two calm songs. Your love interest has a song too: it fades in when they are close or when you talk', 'The Starlight Lounge is a full party now: light-up dance floor, DJ Nova on the decks, lasers, strobes, a dancing crowd and a four-song playlist. The President of the New United States is there. He is having a great time', 'The first time you board your ship you get a short film of it (skippable after a few seconds)', 'Settings: Music can be Soundtrack, Ambient, Beep boop or Off, plus a music volume slider', 'Menu is now a pull-up drawer: swipe up or tap the MENU tab at the bottom (Tab on keyboard). Buttons are light and see-through']},
  { id: 59, title: 'The Prologue', items: ['The first-time-aboard film is now a Prologue: a tour of the whole galaxy (Earth, Mezar, Capitone, Robot City, the Zeltac Ship), the rise of Drome and his fleet, the eye opening in the dark, and your ship launching from Earth', 'Narrated with subtitles for now (voice coming soon). Replay it any time from the Codex', 'In the Starlight Lounge the music now comes from the DJ speakers: louder and clearer up front, panned toward the stage, muffled at the back of the room']},
  { id: 60, title: 'Music Drive and Cinema', items: ['Ship music now comes from speakers on the bridge, along the corridor and in each room', 'First time in the Starlight Lounge: a short intro film (skippable after a few seconds)', 'The Prologue only plays the very first time you board your ship', 'Codex → Cinema replays every cutscene you have unlocked: the Prologue, the Starlight Lounge and the Ending']},
  { id: 61, title: 'Dance floor rules and a roomier screen', items: ['In the Starlight Lounge your weapons are put away: you get a DANCE button instead (click on desktop)', "The President's Nebula Dust now puts a burning cigarette in your hand, and for 15 seconds the music gets louder", 'Settings → HUD size: Small, Medium or Large (phones default to Medium). Settings → Quest tracker: Compact hides the extra text', 'Fullscreen: Menu → Fullscreen or Settings → Fullscreen. If your app blocks it, open the game link in your phone browser', 'Fixed music going silent on some phones and in the Claude app: if the speaker effects mute the music, the game switches them off and keeps playing']},
  { id: 62, title: 'Music fixed', items: ['Music plays again everywhere. The Music Drive is parked while we rebuild it', 'Ship walls, floors and ceilings no longer slide around as you walk', 'Residential Ring: the apartments no longer block the elevator']},
  { id: 63, title: 'The Crucible: raids at Fort Ironrock', items: ['Raids now happen at Fort Ironrock. Use Raid Command (the red terminal by the landing pad, or ask General Hale or Sgt. Torque) to deploy into the Crucible, a hardcore raid arena', 'Pick the deadliness yourself, from Recruit to Apocalypse. Enemies get tougher and hit harder, and the payout grows up to 12×', 'Three waves of elite troops, then the Iron Tyrant with a shockwave you must dodge (get far away or jump). Die and the raid is over', 'Everyone in the Crucible on the same setting fights the same Iron Tyrant: your damage adds up together', 'New healing spells: the Mending Staff (Merla) and Lifebloom Staff (Seer Ixa) heal friends you aim at. Lifebloom also heals friends around them and a little of you', 'Fort Ironrock has its own intro film (replay it in Codex → Cinema), and it only ever plays Tidal Wave']},
  { id: 64, title: 'Game editor (owner only)', items: ['Menu → 🛠 Editor (or F9): place crates, barrels, walls, rocks, trees, lamps, lights, neon signs, platforms and enemy spawns right where you stand', 'Rotate, resize, move, teleport to or delete anything you placed', 'Tune any weapon (damage, fire rate, magazine, price, level) and any enemy (health, speed, XP)', 'Edits save automatically and go live for every player. Save & share copies everything as text']},
  { id: 65, title: 'Gun + staff loadout, and dual wield in New Game+', items: ['Carry a gun and a staff at the same time: equip one of each, then press Y (or tap the ammo box) to switch', 'New Game+ (Ascension 1 and up): switching goes Gun → Staff → BOTH. In both mode you fire your gun and cast your spell together, each with its own ammo and mana', 'The ammo box shows your other weapon and its ammo or mana']},
  { id: 66, title: 'Characters, body type and controller', items: ['Every character now has a permanent ID. Making a new character never replaces an old one, even with the same callsign', 'Start screen → 👥 Characters: switch between all your characters. Characters save automatically to browser & cloud', 'Moving to a different device? Characters → Download file or Copy code, then Upload file or Paste code on the other device', 'Pick ♂ Male or ♀ Female on the start screen', 'Controller: tap LB for the bag, hold LB for gun/staff, heal, codex and dance; R3 heals; D-pad works in menus; A skips cutscenes; rumble when you get hit', 'Wardrobe → Armor: switch Male / Female any time', 'Flying into an asteroid now bounces you off instead of trapping you', 'Removed the old Skip tutorial button']},
  { id: 67, title: 'Cleaner screen', items: ['The minimap now stays north-up; your arrow turns instead', 'The compass is smaller and sits under the minimap', 'Boss health moved out of the middle of the screen to the top-right, under the compass', 'Leave the helm (and other flying prompts) moved to a small chip in the bottom-left', 'Wardrobe shows armor, helmets and faces from the front (capes still from the back)']},
  { id: 68, title: '1.8: Gun sounds, your look, and smoother PC controls', items: ['Gunfire works again: sound effects could get stuck silent after pressing Start. Now any key or tap wakes them up, and iPhones play them even on silent mode', 'Every weapon sounds new: punchy blasters, cracking rifles, booming shotguns with a pump, a whooshing rocket launcher, a twanging crossbow, a buzzing Stinger, and its own voice for every spell element. Reloads, empty clicks, shell casings and explosions are new too', 'New default look: PS1 render, Crisp Toon, Sharp pixels. First launch lets you pick a look (with screenshots) and your music. Change both any time in Menu → Settings', 'PC: closing a menu puts you straight back into aiming (no more wasted shot to grab the mouse). One Esc opens the pause menu. Press 1–9 to pick menu options, 1 gun · 2 staff · 3 melee, mouse wheel swaps weapons, I opens the bag', 'New Game+ only unlocks after you finish the story', 'The end credits play the hymn']},
  { id: 69, title: 'Raid notices out of the way', items: ['The raid chip is now small and sits above your health (top-left on phones) instead of the middle of the screen', 'The next-raid countdown only shows in the last minute', 'Raid alerts, waves and boss calls show on that chip and in the chat log instead of a big popup']},
  { id: 70, title: '1.9 · Fixes round one', items: ['Arena: the betting card shows while bets are open, then shrinks to a small chip in the corner once the fight starts', 'Earth: the floating lava pool now sits on the ground, and the river bridge reaches both banks', 'Other players now see the actual gun or melee weapon you are holding, and see you dancing', 'Starlight Lounge: no weapons in your hands', 'Zeltac: you only see players on your own floor', 'Chat still shows when quests are hidden', 'Ship and indoors: the jetpack no longer pushes your head through the roof', 'Ship exhaust comes out the back now, with new colors in the ship shop (Exhaust tab)', 'The President party button only shows when you are right next to him', 'PC: fixed the mouse randomly jumping. After a menu, click once to take back aiming (that click does not shoot)']},,
  { id: 71, title: '2.0 · The menu tablet', items: ['The menu is now a tablet your character holds up. Six big buttons: Ship, Vehicles, Bag, Journal, Social and Settings', 'Ship holds Beam up, Launch, Galaxy map and Decorate. Vehicles holds your vehicle, bike and drone. Unstuck lives in Settings', 'Settings and the pause screen have four tabs (Graphics, Sound, Controls, Game), so nothing scrolls', 'Long shop and sell lists show a page at a time with arrows (arrow keys work too)', 'PC: Tab opens the tablet, number keys pick a button, Esc or Backspace goes back']},
  { id: 72, title: '2.1 · Shared world, bag equip, balance', items: ['Everyone in the same world now sees the same monsters in the same places, with the same health. Hit one together and it dies for everybody, and everyone who hurt it gets the kill and loot', 'The bag lists your guns, staffs and melee weapons with an Equip button', 'Balance: the Backpack Minigun, Storm Rifle and Marshal Repeater hit less hard, levels add less damage, and gun upgrades are +8% per tier']},
  { id: 73, title: '2.2 · Bubble City grows', items: ['Bubble City has three new domes joined by glass tunnels: the Bubble Market (Auntie Nacre buys and sells), the homes dome (Old Barnacle and Pip) and a kelp farm (Farmer Kelpa)', 'A Pearl Fountain and benches in the main dome, fish schools circling the city, a parked sub and buoys', 'Walking out of a dome no longer pops you up to the surface. You start swimming from the sea floor', 'Siege Bots: legs are attached to the body again and stand on the ground']},
  { id: 74, title: '2.3 · The Art of War', items: ['A new opening trailer, The Art of War, set to the Rising Sun song: the battlefield, the general, a lone warrior, the fallen masterpiece and a statue of rubble, then the galaxy and a fleet battle', 'It plays once when you start a new game, and you can replay it any time from Codex, then Cinema', 'The big eye boss, the Watcher in the Maw, now fights to Event Horizon Collapse', 'Cutscenes in the Codex always switch to their own music', 'Cutscenes play their music even when the game music is set to Ambient or Beep boop (Off still keeps them silent)']},
  { id: 75, title: '2.4 · Velocity, the magnet storm planet', items: ['Velocity is now a flat plain of gray glass under a storm that never ends: lightning bolts, rainbow rain and fog that rushes past as you speed up', 'Pit Row floats 20 m above the plain on magnet pylons, with a long ramp bridge down to the start line', 'Hover driving: cars slide on magnets with almost no friction. Hold Space (or DRIFT) to drift, which charges a boost when you let go. Shift boosts', 'C (or CAM) switches between hood, chase and far chase cameras. Your car has headlights', 'Three new courses across the open plain with ring gates: Storm Sprint, Magnet Mile and Thunder Run, on the shared leaderboards', 'Garage Gus sells five levels of Engine, Magnets and Boost, plus stripe colors and patterns', 'Every car is rebuilt with hover pads, lights and paint, and there is a new Hover Bike', 'Other players see you in your car']},
  { id: 76, title: '2.5 · Aim comes right back', items: ['Closing a menu, the bag, a shop or the tablet takes the mouse back for aiming on its own. No cursor on screen and no extra click', 'If the browser blocks it for a moment (right after Esc), the cursor stays hidden and your next click only grabs the mouse, it never fires']},
  { id: 77, title: '2.6 · New backpack', items: ['The bag (I) is now a full inventory screen: equipment on the left, a 60 slot grid in the middle, item details on the right', 'Filter by Weapons, Medical, Materials, Quest, Valuables or Misc, search by name, and sort by type, rarity, weight, value or newest', 'Equip guns, staffs, melee weapons, armor and ordnance from the bag. Drag items onto slots on PC, or tap Move then tap a slot on phones', 'Four quick slots on keys 4 to 7 (buttons on phones) for medkits, weapons and ordnance. They point at your real items, never copies', 'Pickups show a small card with the item. When the bag is full the loot stays on the ground and tells you, instead of vanishing', 'Drop 1, half or a whole stack. Quest items can never be dropped', 'The lava pit in the Maw on Vector now sits down in the crater floor instead of floating above it', 'The Art of War opening trailer is put away for now. New games start with the usual intro']},
  { id: 78, title: '2.7 · Ship storage and room upgrades', items: ['Own a Cargo Bay? Select loot in your bag and Beam it to your ship. Open Ship storage from the bag or the new terminal in the Cargo Bay', 'Ship storage holds 100 slots and doubles with each Cargo Bay level. Level 5 is the Black Hole Box: unlimited storage, and it sits spinning in your Cargo Bay', 'Take items back out aboard your ship. From Cargo Bay level 3 you can beam them down anywhere', 'Every room now upgrades to level 5 at the Engineering terminal: better rest, more ordnance charges, cheaper gun mods, stronger stims, faster gardens, faster vehicles and boss bonus credits', 'Loot now stacks up to 25 per bag slot (medkits 10), so big hauls fill the bag and storage matters. Nothing you already carry is lost']},
  { id: 79, title: '2.8 · The outlaw underworld', items: ['Outlaw rep: crimes raise it, good deeds lower it. Clean, Shady, Outlaw, Wanted, Most Wanted. Your tier shows on the HUD; tap it for your record', 'Every planet has a hidden hatch on the outskirts leading down to the Underworld: Sly Marlo the Fence buys contraband, Madame Vex runs the black market', 'McKlunkies stands on every planet: burgers and fries heal you, and the back counter buys illegal goods once you are Shady', 'Contraband has a red triangle and only Fences buy it. Stores won\'t touch it', 'Scavengers and drifters roam outside the cities. They leave you alone unless you start it', 'Go Wanted and the Marshals put a growing bounty on you and send hunters. Pay Marshal Rook 1.5x the bounty to clear your name, or use Forged Papers', 'Signed-in players share one board: clean players take Marshal bounties on Wanted players, outlaws post and take Hits in the Underworld. You can only fight a player while one of you holds the contract on the other, and they can fight back', 'Raid Merchant Haulers in space for contraband. Wanted pilots get chased by Marshal patrols', 'New Zeltac floors: The Undercroft and the Senate Archive, with a four-part story about the President\'s money'] },,
  { id: 80, title: '2.8.1 · Bubble City fixes', items: ['Auntie Nacre, Old Barnacle, Farmer Kelpa and Pip were standing in open water outside Bubble City. They are back inside their domes', 'Anyone swimming outside the domes, other players included, now wears a glass dive dome over their head'] },
  { id: 81, title: '2.9 · Substances and the Lab', items: ['New optional system, off until you switch it on in Settings → Game → Substances', 'Legal boosts at every general store: Focus Fizz (+15% XP), Stim Patch (+15% speed), Iron Gum (take 10% less damage)', 'Illegal ones with a red triangle: Void Spice, Neon Dust, Glimmer and Red Haze from Madame Vex or the McKlunkies back counter. Bigger boosts, wild colors, and a chance of a bad trip with shadow figures and whispers', 'Build a Lab on your ship to brew them from materials. It is the only place to cook Blackout. Owning one keeps you Wanted until you tear it down at the Lab console', 'Take one from the bag, the ✦ chip on the HUD, the new USE button on phones, or press U'] },
  { id: 82, title: '2.9.1 · Decorate, pop-ups and the President', items: ['Decorate now lives in the Ship menu. It is greyed out until you are inside your ship', 'New compact build bar at the top of the screen, and the HUD gets out of the way while you decorate', 'The piece you are placing shows as a see-through copy with a yellow arrow out of its front, and turns in all four directions', 'Pop-up messages are now a small see-through pill near the bottom, and area names are smaller', 'President Starling wears a real gold power suit now instead of a box'] },
  { id: 83, title: '2.10 · Editor place mode', items: ['Editor → Place → Place mode: a see-through preview sits wherever you aim, with a yellow arrow for its front. Fire or Place drops it, and you can keep placing', 'Grid on snaps to half metres and 45° turns; Grid off places freely in 15° turns. Arrow keys nudge (Shift for bigger steps), Q/E turn, PgUp/PgDn raise and lower. Phones get a nudge pad', 'Aim at something you placed to Move, Copy or Delete it. Undo takes back the last 20 changes', 'New hanging lamp, chain light, hanging plant and banner. They hang from the ceiling, or get a post outdoors. Ship Decorate has them under Decor', 'Aim at any NPC to move them, turn them, or rewrite what they say', 'New Shops tab: what stores pay for loot and which guns each gunsmith sells. The Enemies tab now sets each spawn group’s levels and count, and can move a spawn area to where you stand'] },
  { id: 84, title: '2.11 · The fishing update', items: ['You now hold your rod while you fish, and other players see it in your hands. Basic, Hive and Frost rods each have their own look', 'New Abyss Rod from Old Marlin on Ocean World (6,000 cr): the biggest catch window and the best odds of rare fish', 'A real cast: swing the rod and the bobber arcs out onto the water. It bobs while you wait, dips with a splash on a bite, and gets pulled in as you reel', 'The fishing box is now a small panel so you can watch the water. Click or tap the screen to reel', 'Every catch swings up in front of you with its name, size and rarity (Common, Uncommon, Rare or Legendary). Your biggest of each species is saved, so watch for New record!'] },
  { id: 85, title: '2.11.1 · Playtest fixes', items: ['Menu rows on phones no longer squeeze names into one word per line (ship upgrades, bounty board and others)', 'Gunsmith and wardrobe previews sit in the corner on phones, so the list and Done button fit without scrolling', 'The New World Discovered card is smaller, see-through, and waits until intro scenes finish', 'Signs and holo ads no longer read backwards when you see them from behind'] },
  { id: 86, title: '2.11.2 · Ocean World quests are back', items: ['The President storyline had accidentally replaced four Ocean World quests (Salt and Subs, Jelly Jam, Pearls for the Mayor, The Sword Master), which also blocked The Deep. They are back, and the President storyline keeps going separately', 'The quest arrow now points you to the Zeltac elevator for the Undercroft and the Senate Archive, and to The Mole once you are on his floor'] },
  { id: 87, title: '2.12 · Story pacing, fishing fights and a livelier ship', items: ['Story pacing: you no longer end up thirty levels above the next chapter. Big quest rewards and boss kills are tuned to their own level, and enemies give less XP once you clearly out-level them.', 'Fort Ironrock\'s war zones, Earth Sky, Zarlich and Vector now match where they sit in the story. Fort\'s training range is still a beginner area, and the war there starts after the Dark Fleet.', 'The President storyline now opens after Robot City.', 'Fishing: a new line-tension fight. Hold to reel, ease off when the line goes red, and watch for big fish making a run. Better rods take more strain and reel faster.', 'Your ship\'s hallway has pipes, crates, lockers, a water cooler, a status screen, a viewport onto the stars, and crew walking the deck who stop for a chat.', 'Phones: the message log keeps the newest three lines, fades sooner and is easier to read. On PC it no longer overlaps the raid button.', 'Long lists like the gunsmith and the Codex get filter buttons: Can buy, Owned, Locked (or Done and To do).'] },
  { id: 88, title: '2.12.1 · A livelier Underworld, and skip the scenes', items: ['The Underworld den has a bartender who sells drinks, Lucky Seven\'s dice table (bet credits, beat her roll, win double), booths, a jukebox, arcade cabinets, and Rattle the information broker with rumors and tips.', 'Settings → Story scenes: set it to Skip and every first-time intro skips itself. Replays from the Codex cinema still play.'] },
  { id: 89, title: '2.12.2 · First-minute fixes', items: ['Phones: the Play button on the Choose Your Look screen was hidden below the bottom edge. It now stays on screen.', 'Enemy and NPC name tags no longer fill the screen when something is right in your face.', 'New players without a ship no longer see raid countdowns for worlds they cannot reach.', 'The galaxy map now says exactly what opens a locked world.'] },
  { id: 90, title: '2.12.3 · Tidier screens', items: ['When you land on a new world, tips and objective pop-ups wait for the world title card instead of landing on top of it.', 'The update log keeps the newest few updates open and folds older ones down to their titles. Tap one to read it.'] },
  { id: 91, title: '2.12.4 · Notebook gallery', items: ['The Start button on the title screen no longer blinks.', 'New checkbox on the start screen: choose whether drugs and drinks are in your game before you begin. You can still change it later in Settings.', 'Codex → Credits → See the drawings: nine of Phil and Caleb\'s high-school notebook drawings, side by side with the characters they became.', 'The ending credits now show some of those drawings too.'] },
  { id: 92, title: '2.13 · The Greater Maw', items: ['New finale: after the Watcher dies, a wormhole tears open near Vector. Only players who beat him can see it. Upgrade your ship first, then fly through.', 'Inside is the Greater Maw, a huge, grosser Watcher floating in a dead star field. You go in alone... until Vega, the Masters and every friend you made show up to help. You can fly back in and fight him again any time.', 'New top ship tier at Zeltac: lasers, hull and engines all get a fourth level.', 'Story fixes: Drome escapes Earth in a shuttle, the Eye in the Dark is set up from the start, Ramick is now a required stop before Robot City, and side quests name the right villain.', 'Vega narrates the trailer.', 'McKlunkies: orders are now taken by a smiling robot face on the wall.', 'Monster levels on later worlds were smoothed so the story never asks you to fight way above your level.', 'iPhone: if something goes wrong the game now shows the error on screen so testers can screenshot it, and it offers a reload if the phone runs out of graphics memory. Phones also render at a lighter resolution in the HD looks.'] },
  { id: 93, title: '2.13.1 · Velocity storm', items: ['Velocity is stormier: heavy fog, a dark sky and a short view distance. The ring gates still glow through it.', 'Rainbow lightning: thick, many-colored bolts strike every few seconds and flash the sky the same color.', 'New default Cockpit camera (C to switch): dashboard, steering wheel that turns with you, your hood in your paint, and rainbow rain on the windshield with wipers.', 'Cars are 12% faster. Gold times were raised to match so medals stay fair.', 'Traffic: hover cars cruise the flats. Hit one and you bounce.', 'Rainbow spray kicks up behind your car.', 'Park and get out: your car now stays where you park it. Walk up and press X or E to get back in, or press X twice from far away to call it.', 'The glassy floor no longer swims and wobbles as you drive (the PS1 jitter is now off for the big flat pieces).'] },
  { id: 94, title: '2.13.2 · Bridges, lakes and alien fish', items: ['Bridges on Earth and Capitone no longer float metres above the ground: they now run bank to bank and slope to meet both sides.', 'The Forest of Life path to the Heartwood now has a footbridge over the river.', "Zarlich's Glowing Lake was dry. It holds water now, and you can fish there.", 'Rivers and pools always sit below the water line on every world.', 'New catch card: when you land a fish you see its type, weight (kg and lb), length and value. Bigger than average fish pay a size bonus on the spot.', 'Ten alien fish that look alien: Lanternjaw, Void Gulper, Three-Eyed Gawker, Tentafish, Shard Ray, Violet Spinefish, Jellopod, Star Jelly, Hive Skimmer and the Gearfish. Find them on Mezar, Capitone, Ocean World, Robot City and Zarlich.'] },
  { id: 95, title: '2.13.3 · Velocity, darker', items: ['Your car now waits right in front of you when you land in Pit Row. Walk up and press E or X to drive.', 'Menu → Vehicle now lets you pick which car to drive. On Velocity it lists your hover cars; elsewhere it lists your war vehicles.', 'Heavier rainbow rain, a rolling storm-cloud ceiling, and a much darker sky. The flash color of each lightning bolt lights up the clouds.', 'Brighter, longer headlights with a beam you can see in the rain.', 'Windshield rain looks like water now: clear beads with a glint and a dark rim, running streaks, and fine mist the wipers clear.', 'Traffic cars no longer drive backwards, and they have headlights.', 'Some shady locals moved into Pit Row.'] },
  { id: 96, title: '2.13.4 · Guns, a gun range and a real B.U.R.P.', items: ['Every gun got a makeover: sights, a light strip in its color, a muzzle brake and a slide that kicks back when you fire.', 'Alien guns now have a floating energy core, spinning rings and glowing vents, and burst a ring of their own color when fired. Regular guns flip out brass casings.', 'Other players now see your gun with its paint, and see it flash and fire.', 'New ship room: the Gun Range (1,200 cr and 6 circuits). It is the one place on the ship you can shoot, with free ammo, pop-up targets and a 30 second drill. Beat your best score for credits.', 'B.U.R.P. has a real robot voice now instead of the browser speech.'] },
  { id: 97, title: '2.13.5 · Cockpits, radio and the Halo Line', items: ["Ship cockpit: press C in space (or the camera button) to fly from the pilot's seat, with a live radar, hull and weapons screens, and a stick and throttle that move", "Ship ammo: 1 Lasers, 2 Plasma, 3 Flak, 4 homing Missiles (6 in the rack, they reload), 5 EMP that freezes raiders around you", "Radio: press R (or the radio button) in your ship or Velocity car to flip through four stations made from the soundtrack", "Bobbleheads: 9 to earn. They ride on your dash and wobble when you turn. N swaps them", "Velocity car cabin rebuilt: a live gauge cluster, a real steering wheel, a center screen with radio and traffic radar, vents, doors, mirror and storm-colored mood lights", "The Halo Line on Velocity: drive into the gates at the east and west edges and ride a magnet tube around the planet, past the glass window onto Prism Deep, the rainbow city of the Hydrans", "Velocity: lighter layered rain, a dark wet road with puddles, cars that hover on the magnet field and shed water, smoother steering at speed", "Robot City's Hover Cup ring race is retired. Zip now sends you to Pit Row on Velocity", "The Starlight Lounge bass now thumps, heavier near the speakers", "Other pilots in space are easier to spot: beacons, readable name tags, and ships that pitch and bank", "B.U.R.P.: 67 new recorded lines (fishing, the gun range, races, Velocity, low health, standing around) and a 60-second B.U.R.P. trailer in Codex, Cinema", "Balance: weak guns and staffs hit harder, and bounty rewards were evened out"] },
  { id: 98, title: '2.13.6 · A cleaner Velocity, the Halo Run and fixes', items: ["Velocity driving screen: health, drone, pet, heal and the raid tracker step aside while you drive, and the drive hints fade after ten seconds", "Speed now reads in mph, and the hover cars hum a deep magnetic drone", "Drift, Boost, Use and Camera sit together in the bottom-right corner", "Halo Run: a new race out the east gate, all the way around the planet in the Halo Line, and home through the west gate", "Blacklights over the Halo Line ramps, and the tunnel barrels now run back into the cliff wall", "Your car has a proper floor and footwell, so the road no longer shows through under the dash", "The radio lives in your ship: turn it on at the console by the bridge window. It plays on board and while you fly; everywhere else you hear the normal soundtrack", "The hall viewport now looks out on open space: a field of stars and the odd ship passing by (kept light so phones stay smooth)", "Lab: a live countdown to the next dose, a sign over the vat, and switching recipes no longer throws away finished doses", "Raid tracker button is now a Settings switch (Game tab), off by default. Raid pop-ups still show", "Galaxy map and pause menu fit sideways phones"] },
  { id: 99, title: '2.13.7 · Fire everything, hold to heal, and a shipwright bay', items: ["One Fire button now fires every weapon your ship has fitted. The ammo picker is gone; buy plasma, flak, missiles and EMP as weapon mounts from Brakka or the bridge terminal.", "Hold Heal to top up until full. It only opens a new medkit when it needs one, and keeps the rest banked.", "New Repair button while flying: hold it to patch the hull, 2 cr per point, never more than needed.", "Flight buttons sit where the driving ones do. The radio and the lasers box are gone.", "Brakka has his own shipwright bay in the Zeltac lobby, welding away on a ship up on stands.", "Menus no longer flip through pages. Lists scroll, while the picture and Done always stay on screen. The gun mod bench shows paint, rounds and ordnance together.", "Backpack on a sideways phone: item details sit in two columns, with the buttons pinned.", "The ship hall window shows stars edge to edge, and a CREW QUARTERS door opens onto the crew's bunks.", "Planet name tags in space are now a setting, off by default."] },
  { id: 100, title: '2.13.8 · The Maw fight, rebuilt', items: ["The intro cutscene now plays every time you take on the Maw.", "The Greater Maw is bigger and nastier: bone armour, a crown of teeth, more eyes, glowing cracks and whipping tendrils.", "It fires purple rings now. Its spawns hold the line between you and it, with a red glow so you can see them.", "Your squadron's lasers fly all the way in and burst on its hide. No more name tags; your allies talk over comms instead.", "Not everyone makes it home. B.U.R.P. takes it hard.", "A final phase: the Maw morphs, the squadron forms up around you, and B.U.R.P. offers fight mode. Mega guns, explosions, smoke, and Vega yelling to keep firing.", "Fight comms are a small strip at the bottom of the screen, out of your way.", "The Greater Maw is in the 3D Asset Studio, so you can edit it there."] },
  { id: 101, title: '2.13.9 · Every place has a sound', items: ["Ambient sound everywhere: ship hum and vents, birds on Earth, desert wind on Mezar, surf on the Ocean World, crowd murmur in the Zeltac and the arenas, machines in Robot City, thunder on Zarlich, and the Maw's low groan.", "Rain, acid rain, snow and sandstorms add their own layer outdoors.", "It sits under the music, crossfades as you travel, and has its own Ambience slider in Settings → Sound."] },
  { id: 102, title: '2.13.10 · Lab stations and a steadier garage', items: ["The Lab keeps everything it makes. Switching a recipe moves finished doses to a lab shelf, and Collect empties the shelf and every station into your bag.", "Build up to 3 lab stations, each brewing its own recipe side by side.", "Two-column lists on a sideways phone (like Garage Gus) no longer flip to one column and back when you tap something."] },
  { id: 103, title: '2.13.11 · Lab fixes', items: ["The Lab list no longer jumps back to the top while you scroll.", "Each lab station now shows what its drug does and what a dose costs.", "The Add station row is laid out properly on a sideways phone."] },
  { id: 104, title: '2.13.12 · The real ending', items: ["The Greater Maw's last, morphed phase takes longer to burn down.", "Killing the Greater Maw for the first time rolls a new ending and the credits straight away, with the whole squadron flying home through the wormhole. Afterwards you land in New Jamestown next to Captain Vega.", "On touch screens, the USE button sits in the right-hand button column, and the gun and ammo box moves next to your HP so FIRE never covers it.", "The menu tiles have new icons drawn from the game's own 3D models, and the text no longer spills over the tiles outside fullscreen."] },
  { id: 105, title: '2.13.13 · Voice packs', items: ["B.U.R.P. can now come in more than one voice. When there's more than one voice pack, pick yours in Settings → Sound.", "Behind the scenes: a Script Studio for editing B.U.R.P.'s lines, cutscene captions and the battle radio, and for making new voices."] },
  { id: 106, title: '2.13.14 · Orchestral Mayhem', items: ["The Greater Maw's last phase has its own soundtrack, Orchestral Mayhem, looping until it dies.", "B.U.R.P. cheers you on through fight mode with new lines."] },
  { id: 107, title: '2.14 · The Art of War, remastered', items: ['The opening film for new troopers is back and rebuilt: a burning sunset over the battlefield, smoke columns, real fire, a proper fireball, and a giant stone trooper rising from the rubble.', 'Vega now narrates it out loud, and the space battle has a full sky of stars and nebulae. Replay it from Codex, then Cinema, or skip it with Settings → Story scenes.', 'The Prologue aboard your ship has stars all around every shot.', 'Port Kelp: the side docks now run out to sea instead of into the huts, the fishing docks line up with them, and the lighthouse stands on solid ground.', 'The skeletons on Vector lie the right way, ribs arching over the spine.', 'Phones no longer flash a half-built start card while the game loads.'] },
  { id: 108, title: '2.14.1 · Moon quest fix', items: ['Breathing Room on the Moon can be finished again: moon mites keep dropping O2 Filters until you have all four. Before, they stopped after the first one.', 'The same fix lets Sky City droid chips keep dropping until you have the five the quest asks for.'] },
  { id: 109, title: '2.14.2 · One weapon button, model icons everywhere', items: ['Phones: tap the weapon box to cycle gun → staff → melee. The separate SWAP button is gone and Reload takes its spot.', 'The weapon box stays the same size and in the same place whichever weapon you hold.', 'Every button inside the menu tablet (Ship, Vehicles, Journal, Social, Settings) now has a little icon made from the game\'s own models.', 'If something breaks on a phone, the red error box now lists every error in order, first one on top, so testers can screenshot the real cause.'] },
  { id: 110, title: '2.14.3 · Vega narrates every cutscene, iPhone fix', items: ['iPhones and iPads: the game no longer crashes on load (Safari has no mouse lock, and one line assumed it did).', 'Vega, the voice from the opening film, now reads every cutscene and the prologue out loud. Shots wait for her to finish.', 'Opening film: the stray "And…" is gone, your wingmen fly in formation beside you, the enemy fleet is spread out and mixed, the battle has six kinds of robots, and dropped guns lie flat on the ground.', 'Prologue: the stars are smaller and calmer, and the odd ball of stars around one planet is gone.'] },
  { id: 111, title: '2.14.4 · A real hangar, a proper catch card', items: ['Hangar: the floor pad no longer flickers. Your selected war vehicle now turns on a lit turntable, with a gantry crane overhead, a tool wall, a red tool chest, tyre stacks, fuel drums, a fuel pump and guide lights to the launch door.', 'Fishing: the fish you caught now swims in front of its card, and the card waits for you to tap Continue (or press Enter or E).', 'Phones: the USE button can no longer land on top of the radar.', 'New drawn icons for the camera and repair buttons. The ship and the car share the same camera icon.'] },
  { id: 112, title: "2.14.5 · The Angler's Den, rooms that grow, Vega's film", items: ["New ship room: the Angler's Den. Mount your catches on 12 wall plaques, each showing the fish and your best length. Take one down any time to get the fish back. It also has a rod rack, an armchair and a big aquarium.", 'Upgraded ship rooms now look upgraded. Lv 2 and 3 each add a themed prop, Lv 4 hangs a banner and a second light, and Lv 5 adds gold trim and a crest at the door.', 'Ship corridor: the hull posts no longer stand in doorways, and the crane hook that was floating in the hall is back inside the hangar.', 'Fishing: the Bug Pond, Fern Pond and Coolant Canal are bigger, your cast always lands in water, and Coil in Robot City moved back from the dock.', 'Opening film: Captain Vega is the hero now (you are a fresh recruit), and the soldiers that were standing inside her are gone. Her ship flies the film\'s space battle.', 'Prologue: the ball of stars is gone, the stars are dimmer so the planets stand out, the thing behind Vector is now the Watcher rising out of the dark, and Drome\'s flagship wears a setting-sun sigil instead of a big red dot. With voice off, the prologue no longer stalls on its first line.'] },
  { id: 139, title: "2.19.8 · Inside the Roxy", items: ["Cinema seats face the screen, and moviegoers sit in about ten of them", "You walk on the tiered floor instead of sinking through it, and the seats sit on their tiers", "The Roxy has just its marquee out front: the old building sign behind it is gone, and the street lamp no longer stands in the doorway"] },
  { id: 140, title: "2.19.9 · Roxy touch-ups", items: ["The Roxy marquee and reader board no longer overlap or flicker", "The red carpet sits above the sidewalk instead of flickering through it", "Moviegoers sit with their legs angled down instead of poking through the seats"] },
  { id: 141, title: "2.19.10 · Load fix", items: ["Fixed a crash on load for saves that tracked a quest which no longer exists"] },
  { id: 142, title: "2.19.11 · Posters & graffiti", items: ["Eight poster designs now hang on walls across the universe: bars, the underground, ship halls and town buildings", "Spray-paint graffiti tags turn up on walls too"] },
  { id: 143, title: "2.19.12 · Grub's Bar", items: ["The Undercroft bar is now Grub's Bar, with a cyan neon sign", "Hanging chain lamps, a back wall of glowing bottles, beer taps and mugs on the counter", "Tables with red stools, arcade cabinets and junk on the floor"] },
  { id: 144, title: "2.19.13 · Ship fixes", items: ["The galaxy map railing on the bridge is solid now, with the opening at the front", "Crew no longer walk through the front of the hall by the bridge"] },
  { id: 145, title: "2.19.14 · Fewer posters", items: ["Posters and graffiti now only appear on Earth, and fewer of them"] },
  { id: 146, title: "2.19.15 · Grub's Bar in the Underworld", items: ["Grub's bar in the Underworld gets a cyan neon sign, glowing neon bottles, bulb chandeliers on chains, beer taps and mugs", "Regulars sit at the bar and at two new tables; dark floor with junk scattered about"] },
  { id: 147, title: "2.19.16 · Crew for hire", items: ["Seated people in the theatre and the bar now sit properly, with their knees bent at 90°", "More regulars in the Underworld: a couple eating in a booth, a deal going down in a new booth, two talking business", "Hire crew from Grub: a Runner fetches Lab materials, a Cook brews extra doses, a Dealer sells your product for credits", "One crew slot to start, two at level 15, three at level 30. Crew can get killed on the job, so check back at the bar for replacements", "Manage your crew from the Lab terminal on your ship"] },
  { id: 148, title: "2.19.17 · The Glonk Trio", items: ["A cantina band plays on a little stage in the Underworld: a keytar, a theremin and glowing drum pods", "The Underworld now plays Glinky Glonky and Crooked Clarinet"] },
  { id: 149, title: "2.20 · Hand-made UI", items: ["New hand-drawn pixel windows and buttons: framed panels with brass rivets, chunky bevelled buttons that press down", "Every menu uses the game's pixel font", "No more see-through glass panels or emoji in menus"] },
  { id: 150, title: "2.20.1 · Save fix", items: ["Fixed a crash on the start screen when a cloud save loaded read-only data"] },
  { id: 138, title: "2.19.7 · Roxy entrance and arcade fixes", items: ["The Roxy's doors and posters sit on the building front, with the marquee canopy and red carpet reaching out over the sidewalk", "The grey apartments behind the arcade turned to face the alley and moved back so they no longer press against the arcade", "Arcade cabinet side art no longer flickers as you walk past"] },
  { id: 137, title: "2.19.6 · Hand-painted town and plant textures", items: ["New pixel textures: brick for shops and the garage, stucco for homes and Town Hall, shingle roofs, and bark on tree trunks", "Building textures now tile at real size instead of one tile stretched across a whole wall", "New leaf and grass textures for every tree, bush and field in the game, with pixel clumps, highlights and tufts instead of blurry blobs"] },
  { id: 136, title: "2.19.5 · Signs and town fixes", items: ["Every sign in the game is now a pixel-art plaque with a bevelled frame, rivets, a pixel font and a drop shadow, and it is painted to the shape of its board so text is never squashed or stretched", "Fixed mirrored copies of two-sided signs (like the notice board and the arcade marquees) floating in the fields outside town", "The Roxy now faces West Avenue, so the park pond is behind it instead of at the door", "Houses no longer poke through the city wall: the apartments moved inward, two small houses were trimmed and three that could not fit were removed", "Town Hall columns stand out from the facade instead of inside it", "Street trees moved off the curb onto the sidewalk"] },
  { id: 135, title: "2.19.4 · New Jamestown, tidied up", items: ["Streets are clear: the scattered stalls, crates and bins are gone from the roads, and no bushes grow through the pavement", "One market row of four stalls on East Avenue, and a bench, bin and hydrant at each corner where the streets leave the plaza", "Parked hover cars sit at the curb instead of on the sidewalk", "Slick Eddie and Viper work the two back alleys west of Main Street, with crates and a dim lamp in each", "Arthur Vance's signing booth moved off West Avenue onto the sidewalk, the notice board moved off Main Street, and Bobby's BBQ no longer clips into the house behind it", "The Aranus Man comic reader matches the game's look, and its pages load much faster", "The Fort Ironrock iron wall texture now gets the same smoothing as every other texture in the HD styles"] },
  { id: 134, title: '2.19.3 · Fort Ironrock Armored Perimeter Walls', items: [
    'Fort Ironrock perimeter wall armor: The circular perimeter wall enclosing Fort Ironrock is now reinforced with riveted heavy iron plates, corner bolts, rust seams, and gunmetal coping caps.',
    'Retro graphics alignment: All new surfaces and structures pass through the authentic PS1 shader pipeline (discrete toon ramp, 320×240 vertex grid snapping, and affine texture warping).',
    'Custom texture asset: Embedded 64×64 pixel art riveted steel plate texture (TEX.ironwall) with nearest-neighbor filtering and repeat wrapping.'
  ] },
  { id: 133, title: '2.19.2 · New Jamestown Town Life · Stimulants, Arcades & Gazette', items: [
    'Stimulant dealing with Arthur Vance: Sell Focus Fizz, Stim Patches, Void Spice, and more to Arthur at his signing booth to fuel his writing on Issue #2. Focus Fizz pays a 2× premium (120 cr)!',
    'Playable retro arcade cabinets: Two full-sized coin-op cabinets (Space Snake & Space Rocks) stand outside the Neon Arcade on West Street, ready to play for high scores.',
    'Arcade Champion Pixel Pete: Hang out with Pete by the machines to talk high-score strategies and retro gaming.',
    'Feed Barnaby fresh fish: Treat Barnaby the cat to any fresh catch from Gil\'s Fish Market for a full heal, +50 XP, and a 10-minute Feline Agility (+15% move speed) buff.',
    'Cookie\'s Diner specials: Order savory Space Meatloaf (+10% dmg), piping hot Black Coffee (+15% speed), or Warm Cherry Pie at Cookie\'s Diner, complete with outdoor checkered cafe tables.',
    'Municipal Notice Board: Read local town bulletins, cinema showtimes, lost-and-found notices, and your active Outlaw Rep & Wanted status at the Central Plaza board.',
    'Cinema soundscape: Added dedicated auditorium acoustic profile with lowpass room wash, projector hum, and theater reverb.'
  ] },
  { id: 132, title: '2.19.1 · The Roxy Cinema & Dual-Channel Movies', items: [
    'The Roxy Cinema: walk into New Jamestown\'s grand movie palace on the west entertainment strip, featuring an art-deco neon marquee, double movie posters, ticket window, and double doors.',
    'Cinema auditorium: indoor screening room with sloped stadium seating tiers, plush red velvet armchairs, aisle step lights, proscenium velvet curtains, and concession stand with hot butter popcorn.',
    'Giant silver screen: 14.4m x 8.1m screen with black velvet framing borders, ambient screen glow illuminating the auditorium, and a volumetric projector beam shining from the projection booth.',
    'Dual-channel movie catalog: enjoy Night of the Living Dead (1968, CH 1) and Santa Claus Conquers the Martians (1964, CH 2) with independent timestamp progress.',
    'Channel switching: press C or use the TV/theatre prompts to change channels anytime in the cinema or on the ship\'s fishing room couch.',
    'Inactivity auto-hide: while seated and watching the film, on-screen prompts and buttons smoothly fade away after 2.8 seconds of inactivity, immediately restoring upon any mouse or keyboard input.'
  ] },
  { id: 131, title: '2.19 · New Jamestown Revamp & The Astonishing Aranus Man', items: ['New Jamestown full city overhaul: distinct civic, commercial, entertainment, residential, and park districts with brick facades and slate mansard roofs.', 'Arthur Vance book signing booth: meet the author of The Astonishing Aranus Man, read the 10-page in-game comic book, help his writer\'s block, and fix the Arena match for an exclusive Aranus Cape and signed comic.', 'Shady street runners: recruit Slick Eddie and Viper in the alleys to move product across the city using your Outlaw reputation.', 'Bobby the Grillmaster: sizzling backyard BBQ kettle grill behind the diner with hot space patties.', 'Barnaby the Cat: friendly neighborhood orange tabby in the park you can pet for purrs and warm fuzzies.', 'First-person inhaler animation: taking substances now shows a custom inhaler with clear glass chamber dynamically glowing in the drug\'s color.'] },
  { id: 130, title: "2.18.12 · Bridge layout", items: ["The galaxy map and the captain's chair sit a little further back on the bridge"] },
  { id: 129, title: "2.18.11 · Cleaner terminals", items: ["Room terminals are plain bridge consoles again, with no screen above", "Removed the floating screen beside the drone bay"] },
  { id: 128, title: "2.18.10 · Room terminals and the drone bay", items: ["Every ship room terminal now matches the new bridge consoles, with a screen above", "The drone bay moved behind the two upgrade consoles and got a new cradle with a hovering drone"] },
  { id: 127, title: '2.18.9 · Captain\'s chair and the Marshal terminal', items: ['A proper captain\'s chair on a swivel base with armrest controls', 'The Bounty terminal is a real console with a Marshal star screen'] },
  { id: 126, title: '2.18.8 · Bridge, finished', items: ['A ceiling dome with a glowing ring over the map, cable runs and light panels', 'The galaxy map sits on a railed platform with a planet hologram', 'Framed wall panels with status lights replace the blue strips'] },
  { id: 125, title: '2.18.7 · A nicer bridge', items: ['The ship bridge has neat new consoles with screens and buttons, glowing floor trim, wall light bars and ceiling ribs'] },
  { id: 124, title: '2.18.6 · A tougher Maw', items: ['The Greater Maw has twice the health, last phase included', 'Its teeth point the right way'] },
  { id: 123, title: '2.18.5 · Kids swing their arms right', items: ['Kids in the Residential Ring swing their arms from the shoulders'] },
  { id: 122, title: '2.18.4 · Easy furniture removal, chat closes', items: ['While decorating your ship, look at a piece and press E to remove it (or click it in Remove mode)', 'Chat closes again with Enter or Escape'] },
  { id: 121, title: '2.18.3 · Leaderboards on your own server', items: ['Leaderboards, the Marshal board and the Hit board now work when the game is played from server.js (like through your tunnel), not only on the claude.ai page'] },
  { id: 120, title: '2.18.2 · New den wallpaper', items: ['New fish wallpaper in the Angler\'s Den, drawn by Phil'] },
  { id: 119, title: '2.18.1 · Worm Hole line', items: ['At the Worm Hole the fishing line now comes from the tip of your rod'] },
  { id: 118, title: '2.18 · Codex items', items: ['New Items tab in the Codex: every item in the game, with who drops it, who sells it and which quest gives it', 'Items fill in as you find them; locked ones show ??? but still tell you where to look', 'Search by item, enemy or world, and filter by category with found counts'] },
  { id: 117, title: '2.17.2 · Den comforts', items: ['The TV switch only shows up when you stand right at the TV, so you can watch from the couch', 'Ship music pauses while the den TV is on and comes back when you turn it off or leave', 'Tan wallpaper with little fish in the Angler\'s Den', 'The Worm Hole camera tilts up so you can see the whole TV while you fish'] },
  { id: 116, title: '2.17.1 · New type and the movie', items: ['New fonts: Tektur for titles and headings, WDXL Lubrifont TC for reading text and chat', 'Night of the Living Dead now plays on the Angler\'s Den TV', 'The high-low table\'s cards and chips sit on the felt, and the stools are on the players\' side'] },
  { id: 115, title: '2.17 · Movie night in the Angler\'s Den', items: ['The Angler\'s Den has a TV playing Night of the Living Dead (1968). It remembers where you stopped, pauses when you leave the room and turns the ship music off while it plays', 'A couch you can sit on. Move to get up', 'Angler\'s Den Lv 5 adds the rainbow Worm Hole: an ice-fishing hole that can bite with any fish in the game. You can fish it from the couch while the movie plays', 'Ice holes use a short jigging rod held low over the hole', 'The rod rack stands the rods up instead of leaving them on the floor, and the speaker no longer covers a trophy plaque', 'The Jellopod\'s tentacles trail behind it now', 'Every helmet is built once per trooper, fixing helmets that crashed in game but previewed fine'] },
  { id: 114, title: '2.16 · Side hustles, a clearer ocean and Vega on the radio', items: ['Sell drugs to the President (he pays way too much) and to random people. Some refuse, and in lawful places someone might report you', 'Give your partner product to sell from their apartment or your ship quarters, then collect the earnings. Push it too hard and they get arrested; post bail with Marshal Rook', 'Your bag shows one tile each for guns, staffs, melee and ordnance with a picture of the weapon. Tap it to pick from the whole list. Weapons and ordnance no longer take bag space or weight', 'Ocean World cleaned up: no torn water, no domes showing through the surface, floors sit on the seabed, no sky underwater, taller glass tunnels', 'Every world\'s water matches its colors', 'Vega is the only voice in the cutscenes and does all the battle radio at the Greater Maw, fully voiced', 'New space fonts and a light space blue in place of the orange', 'Fullscreen works in more browsers. On iPhone, Add to Home Screen to play fullscreen', 'The casino carpet no longer flickers and the high-low table looks like a table', 'Mezar shows its name on the galaxy map'] },
  { id: 113, title: '2.15 · The Lucky Asteroid, the Undercroft dive and a bigger lounge', items: ['The Neon Arcade has a casino now: the Lucky Asteroid. Six slot machines, a high-low table and a space poker table with Rook and Nyx. Win real credits', 'Two playable arcade cabinets: SPACE SNAKE and SPACE ROCKS. Good scores pay out a few credits', 'The Undercroft is a proper hive of scum and villainy: the Rusty Rivet bar, a band, back-room poker with One-Eye Jax, a members-only back room, wanted posters, drunks and smoke', 'The Starlight Lounge got a second bar, VIP couches, plants, waiter bots and people mingling. The President has his own spot and the dancers no longer walk through him', 'When a person and a thing are both in reach (like your partner and your bed), the one you are looking at gets the button. Your roommate also stands away from the bunk now', 'Romance music only plays while you are talking to them', 'Q, Y and the weapon box all cycle gun, staff, melee. Staffs are their own magic slot again', 'The weapon box stays the same size for ammo, spells and the shield', 'New energy shield: a glowing kite shield with the setting-sun sigil', 'Muzzle flashes now come out of the end of each barrel', 'Earth no longer shrinks and vanishes when you look at it from the Moon'] },
];
const UPDATES_LATEST = Math.max(...UPDATES.map(u => u.id));
function updateRows(list) {
  const rows = document.createElement('div'); rows.className = 'rows'; rows.id = 'shopRows'; rows.style.maxHeight = '46vh'; rows.style.overflowY = 'auto';
  // the newest few open; older ones fold down to their title, tap to read
  list.slice().sort((a, b) => b.id - a.id).forEach((u, i) => { const d = document.createElement('div'); d.className = 'row'; d.style.display = 'block'; const fold = i >= 4;
    const h = document.createElement('b'); h.textContent = (fold ? '▸ ' : '') + u.title; h.style.color = '#ffd36a'; d.appendChild(h);
    const ul = document.createElement('ul'); ul.style.margin = '4px 0 2px 18px'; ul.style.padding = '0'; u.items.forEach(t => { const li = document.createElement('li'); li.textContent = t; ul.appendChild(li); }); d.appendChild(ul); rows.appendChild(d);
    if (fold) { ul.hidden = true; d.style.cursor = 'pointer'; d.addEventListener('click', () => { ul.hidden = !ul.hidden; h.textContent = (ul.hidden ? '▸ ' : '▾ ') + u.title; SFX.ui(); if (typeof pageRows === 'function') pageRows(); }); } });
  $('dlgActs').before(rows);
}
function openUpdates(missedOnly) {
  const seen = S.seenUpd || 0, list = missedOnly ? UPDATES.filter(u => u.id > seen) : UPDATES;
  if (!list.length) return false;
  openDlg(missedOnly ? `${list.length} update${list.length > 1 ? 's' : ''} since you last played` : 'Update log', 'B.U.R.P.');
  $('dlgLine').textContent = missedOnly ? `While you were gone, ${S.nick || 'Trooper'}, the universe got bigger. Here's what you missed:` : 'Everything new, newest first.';
  updateRows(list); acts([['Got it', () => { S.seenUpd = UPDATES_LATEST; markDirty(); closeDlg(); }, true]]);
  S.seenUpd = UPDATES_LATEST; markDirty(); return true;
}
// call on login: veterans see what they missed; brand-new players start caught up
function updatesOnLogin(isNew) {
  if (isNew) { S.seenUpd = UPDATES_LATEST; markDirty(); return; }
  if ((S.seenUpd || 0) < UPDATES_LATEST) setTimeout(() => { if (state === 'play' && !dlgOpen) openUpdates(true); }, 1200);
}
// tester unlock wins over every world's own gate
{ const _po = planetOpen; planetOpen = function (id) { if (DEV_ALL && LEVELS[id] && id !== 'zfloor') return true; return _po(id); }; }
window.openUpdates = openUpdates;
